const AP = 'Estatuto de Roma de la Corte Penal Internacional';
const PREF = 'Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998';
const Q = [
// ── Art. 5 y 6 ──
{a: 'art. 5.1', r: 'Artículo 5. Crímenes de la competencia de la Corte', e: 'La competencia de la Corte se limitará a los crímenes más graves de trascendencia para la comunidad internacional en su conjunto. La Corte tendrá competencia, de conformidad con el Estatuto, respecto de los siguientes crímenes (señale la INCORRECTA):',
 o: ['El crimen de terrorismo internacional.', 'El crimen de genocidio.', 'Los crímenes de lesa humanidad.', 'Los crímenes de guerra.'],
 t: 'La competencia de la Corte se limitará a los crímenes más graves de trascendencia para la comunidad internacional en su conjunto. La Corte tendrá competencia, de conformidad con el presente Estatuto, respecto de los siguientes crímenes: a) El crimen de genocidio; b) Los crímenes de lesa humanidad; c) Los crímenes de guerra; d) El crimen de agresión', p: 'Son cuatro: genocidio, lesa humanidad, guerra y agresión; el terrorismo no figura.'},
{a: 'art. 6', r: 'Artículo 6. Genocidio', e: 'A los efectos del Estatuto, se entenderá por «genocidio» cualquiera de los actos mencionados a continuación, perpetrados con la intención de destruir total o parcialmente a un grupo:',
 o: ['nacional, étnico, racial o religioso como tal.', 'nacional, étnico, racial, religioso o político como tal.', 'nacional, étnico o racial, con exclusión de los grupos religiosos.', 'étnico, racial, religioso o cultural como tal.'],
 t: 'se entenderá por «genocidio» cualquiera de los actos mencionados a continuación, perpetrados con la intención de destruir total o parcialmente a un grupo nacional, étnico, racial o religioso como tal', p: 'Los grupos protegidos son el nacional, étnico, racial y religioso (no el político ni el cultural).'},
{a: 'art. 6', r: 'Artículo 6. Genocidio', e: 'Se entenderá por «genocidio» cualquiera de los siguientes actos perpetrados con la intención de destruir total o parcialmente a un grupo nacional, étnico, racial o religioso como tal (señale la INCORRECTA):',
 o: ['Deportación o traslado forzoso de miembros del grupo.', 'Matanza de miembros del grupo.', 'Lesión grave a la integridad física o mental de los miembros del grupo.', 'Medidas destinadas a impedir nacimientos en el seno del grupo.'],
 t: 'a) Matanza de miembros del grupo; b) Lesión grave a la integridad física o mental de los miembros del grupo; c) Sometimiento intencional del grupo a condiciones de existencia que hayan de acarrear su destrucción física, total o parcial; d) Medidas destinadas a impedir nacimientos en el seno del grupo; e) Traslado por la fuerza de niños del grupo a otro grupo', p: 'El traslado forzoso que constituye genocidio es solo el de niños del grupo a otro grupo, no el de miembros en general.'},
// ── Art. 7 ──
{a: 'art. 7.1', r: 'Artículo 7. Crímenes de lesa humanidad', e: 'Se entenderá por «crimen de lesa humanidad» cualquiera de los actos siguientes cuando se cometa como parte de un ataque generalizado o sistemático contra una población civil y con conocimiento de dicho ataque (señale la INCORRECTA):',
 o: ['El pillaje de bienes de la población civil.', 'Exterminio.', 'Deportación o traslado forzoso de población.', 'Desaparición forzada de personas.'],
 t: 'a) Asesinato; b) Exterminio; c) Esclavitud; d) Deportación o traslado forzoso de población; e) Encarcelación u otra privación grave de la libertad física en violación de normas fundamentales de derecho internacional; f) Tortura; [...] i) Desaparición forzada de personas; j) El crimen de «apartheid»', p: 'El pillaje es un crimen de guerra (art. 8), no de lesa humanidad.'},
{a: 'art. 7.1', r: 'Artículo 7. Crímenes de lesa humanidad', e: 'Se entenderá por «crimen de lesa humanidad» cualquiera de los actos siguientes cuando se cometa como parte de un ataque __________ contra una población civil y con conocimiento de dicho ataque.',
 o: ['generalizado o sistemático', 'generalizado y sistemático', 'sistemático y organizado', 'masivo o planificado'],
 t: 'cuando se cometa como parte de un ataque generalizado o sistemático contra una población civil y con conocimiento de dicho ataque', p: 'Basta que el ataque sea generalizado «o» sistemático.'},
{a: 'art. 7.1.h)', r: 'Artículo 7. Crímenes de lesa humanidad', e: 'La persecución de un grupo o colectividad con identidad propia fundada en motivos políticos, raciales, nacionales, étnicos, culturales, religiosos, de género u otros motivos universalmente reconocidos como inaceptables con arreglo al derecho internacional constituye crimen de lesa humanidad:',
 o: ['en conexión con cualquier acto mencionado en el párrafo 1 o con cualquier crimen de la competencia de la Corte.', 'siempre que se cometa en el marco de un conflicto armado internacional o interno.', 'cuando se cometa en conexión con un crimen de genocidio o con un crimen de guerra.', 'siempre que cuente con la autorización o la aquiescencia de un Estado.'],
 t: 'h) Persecución de un grupo o colectividad con identidad propia fundada en motivos políticos, raciales, nacionales, étnicos, culturales, religiosos, de género definido en el párrafo 3, u otros motivos universalmente reconocidos como inaceptables con arreglo al derecho internacional, en conexión con cualquier acto mencionado en el presente párrafo o con cualquier crimen de la competencia de la Corte', p: 'Se exige conexión con cualquier acto del párrafo 1 o con otro crimen de la competencia de la Corte.'},
{a: 'art. 7.2.a)', r: 'Artículo 7. Crímenes de lesa humanidad', e: 'Por «ataque contra una población civil» se entenderá una línea de conducta que implique la comisión múltiple de actos mencionados en el párrafo 1 contra una población civil, de conformidad con:',
 o: ['la política de un Estado o de una organización de cometer ese ataque o para promover esa política.', 'la política de un Estado o de un grupo armado de cometer ese ataque o de promoverlo.', 'las órdenes de una autoridad militar o civil de un Estado que cometa ese ataque.', 'la política de un Estado y de una organización de cometer ese ataque o para promover esa política.'],
 t: 'Por «ataque contra una población civil» se entenderá una línea de conducta que implique la comisión múltiple de actos mencionados en el párrafo 1 contra una población civil, de conformidad con la política de un Estado o de una organización de cometer ese ataque o para promover esa política', p: 'Política de un Estado «o» de una organización.'},
{a: 'art. 7.2.b) y 7.2.c)', r: 'Artículo 7. Crímenes de lesa humanidad', e: 'Por «esclavitud» se entenderá el ejercicio de los atributos del derecho de propiedad sobre una persona, o de algunos de ellos, incluido el ejercicio de esos atributos en el tráfico de personas, en particular:',
 o: ['mujeres y niños.', 'mujeres y menores.', 'niños y ancianos.', 'mujeres, niños y refugiados.'],
 t: 'Por «esclavitud» se entenderá el ejercicio de los atributos del derecho de propiedad sobre una persona, o de algunos de ellos, incluido el ejercicio de esos atributos en el tráfico de personas, en particular mujeres y niños', p: 'La mención expresa es «mujeres y niños».'},
{a: 'art. 7.2.d)', r: 'Artículo 7. Crímenes de lesa humanidad', e: 'Por «deportación o traslado forzoso de población» se entenderá el desplazamiento forzoso de las personas afectadas, por expulsión u otros actos coactivos, de la zona en que estén legítimamente presentes:',
 o: ['sin motivos autorizados por el derecho internacional.', 'sin motivos autorizados por el derecho interno del Estado.', 'sin autorización previa del Consejo de Seguridad.', 'sin motivos previstos en los Convenios de Ginebra.'],
 t: 'el desplazamiento forzoso de las personas afectadas, por expulsión u otros actos coactivos, de la zona en que estén legítimamente presentes, sin motivos autorizados por el derecho internacional', p: 'Lo decisivo es la ausencia de motivos autorizados por el derecho internacional.'},
{a: 'art. 7.2.e)', r: 'Artículo 7. Crímenes de lesa humanidad', e: 'Por «tortura» se entenderá causar intencionalmente dolor o sufrimientos graves, ya sean físicos o mentales, a una persona que el acusado tenga bajo su custodia o control; sin embargo, no se entenderá por tortura:',
 o: ['el dolor o los sufrimientos que se deriven únicamente de sanciones lícitas o que sean consecuencia normal o fortuita de ellas.', 'el dolor o los sufrimientos que se deriven de sanciones lícitas o de la legítima defensa.', 'el dolor o los sufrimientos que se deriven únicamente de sanciones disciplinarias o de medidas cautelares.', 'el dolor o los sufrimientos que sean consecuencia normal de la detención preventiva.'],
 t: 'Por «tortura» se entenderá causar intencionalmente dolor o sufrimientos graves, ya sean físicos o mentales, a una persona que el acusado tenga bajo su custodia o control; sin embargo, no se entenderá por tortura el dolor o los sufrimientos que se deriven únicamente de sanciones lícitas o que sean consecuencia normal o fortuita de ellas', p: 'Excluye los derivados «únicamente de sanciones lícitas» o consecuencia normal o fortuita de ellas.'},
{a: 'art. 7.2.f)', r: 'Artículo 7. Crímenes de lesa humanidad', e: 'Por «embarazo forzado» se entenderá el confinamiento ilícito de una mujer a la que se ha dejado embarazada por la fuerza, con la intención de modificar la composición étnica de una población o de cometer otras violaciones graves del derecho internacional. En modo alguno se entenderá que esta definición afecta:',
 o: ['a las normas de derecho interno relativas al embarazo.', 'a las normas de derecho internacional relativas al embarazo.', 'a la legislación nacional sobre el aborto.', 'a los derechos reproductivos de la mujer afectada.'],
 t: 'En modo alguno se entenderá que esta definición afecta a las normas de derecho interno relativas al embarazo', p: 'Se salvan las normas de derecho interno relativas al embarazo.'},
{a: 'art. 7.2.h)', r: 'Artículo 7. Crímenes de lesa humanidad', e: 'Por el crimen de «apartheid» se entenderán los actos inhumanos de carácter similar a los mencionados en el párrafo 1 cometidos en el contexto de un régimen institucionalizado de opresión y dominación sistemáticas de un grupo racial sobre uno o más grupos raciales y con la intención de:',
 o: ['mantener ese régimen.', 'perpetuar ese régimen.', 'destruir a los grupos dominados.', 'segregar a los grupos dominados.'],
 t: 'cometidos en el contexto de un régimen institucionalizado de opresión y dominación sistemáticas de un grupo racial sobre uno o más grupos raciales y con la intención de mantener ese régimen', p: 'La intención exigida es la de «mantener ese régimen».'},
{a: 'art. 7.2.i)', r: 'Artículo 7. Crímenes de lesa humanidad', e: 'Por «desaparición forzada de personas» se entenderá la aprehensión, la detención o el secuestro de personas por un Estado o una organización política o con su autorización, apoyo o aquiescencia, seguido de la negativa a admitir tal privación de libertad o dar información sobre la suerte o el paradero de esas personas, con la intención de dejarlas fuera del amparo de la ley:',
 o: ['por un período prolongado.', 'de manera permanente.', 'por un período superior a un año.', 'hasta su aparición con vida.'],
 t: 'con la intención de dejarlas fuera del amparo de la ley por un período prolongado', p: 'La fórmula es «por un período prolongado», sin cifra.'},
{a: 'art. 7.3', r: 'Artículo 7. Crímenes de lesa humanidad', e: 'A los efectos del Estatuto, se entenderá que el término «género» se refiere a los dos sexos, masculino y femenino, en el contexto de la sociedad. El término «género»:',
 o: ['no tendrá más acepción que la que antecede.', 'incluirá también la identidad sexual de las personas.', 'se interpretará conforme al derecho interno de cada Estado Parte.', 'no tendrá más acepción que la que antecede, salvo decisión de la Asamblea de los Estados Partes.'],
 t: 'se entenderá que el término «género» se refiere a los dos sexos, masculino y femenino, en el contexto de la sociedad. El término «género» no tendrá más acepción que la que antecede', p: 'No admite otra acepción.'},
// ── Art. 8 ──
{a: 'art. 8.1', r: 'Artículo 8. Crímenes de guerra', e: 'La Corte tendrá competencia respecto de los crímenes de guerra, en particular, cuando se cometan:',
 o: ['como parte de un plan o política o como parte de la comisión en gran escala de tales crímenes.', 'como parte de un plan o política y como parte de la comisión en gran escala de tales crímenes.', 'como parte de un plan o política de un Estado en el marco de un conflicto armado internacional.', 'como parte de la comisión en gran escala de tales crímenes, previa autorización del Consejo de Seguridad.'],
 t: 'La Corte tendrá competencia respecto de los crímenes de guerra, en particular, cuando se cometan como parte de un plan o política o como parte de la comisión en gran escala de tales crímenes', p: 'Plan o política «o» comisión en gran escala (alternativos).'},
{a: 'art. 8.2.a)', r: 'Artículo 8. Crímenes de guerra', e: 'Se entiende por «crímenes de guerra» las infracciones graves de los Convenios de Ginebra de 12 de agosto de 1949, a saber, cualquiera de los siguientes actos contra personas o bienes protegidos (señale la INCORRECTA):',
 o: ['La toma de rehenes en conflictos armados no internacionales.', 'El homicidio intencional.', 'La tortura o los tratos inhumanos, incluidos los experimentos biológicos.', 'La deportación o el traslado ilegal, o el confinamiento ilegal.'],
 t: 'i) El homicidio intencional; ii) La tortura o los tratos inhumanos, incluidos los experimentos biológicos; [...] vii) La deportación o el traslado ilegal, o el confinamiento ilegal; viii) La toma de rehenes', p: 'La toma de rehenes sí figura, pero entre las infracciones graves de los Convenios de Ginebra (apartado a); la opción la restringe a conflictos no internacionales, lo que no dice el texto.'},
{a: 'art. 8.2.a)', r: 'Artículo 8. Crímenes de guerra', e: 'El hecho de forzar a un prisionero de guerra o a otras personas protegidas a servir en las fuerzas de una Potencia enemiga constituye:',
 o: ['una infracción grave de los Convenios de Ginebra de 12 de agosto de 1949.', 'una violación grave de las leyes y usos aplicables en los conflictos armados internacionales.', 'una violación grave del artículo 3 común a los cuatro Convenios de Ginebra.', 'un crimen de lesa humanidad cuando se cometa de forma sistemática.'],
 t: 'a) Infracciones graves de los Convenios de Ginebra de 12 de agosto de 1949, a saber, cualquiera de los siguientes actos contra personas o bienes protegidos [...] v) El hecho de forzar a un prisionero de guerra o a otras personas protegidas a servir en las fuerzas de una Potencia enemiga', p: 'Está entre las infracciones graves de los Convenios de Ginebra (art. 8.2.a.v).'},
{a: 'art. 8.2.b)', r: 'Artículo 8. Crímenes de guerra', e: 'Constituyen otras violaciones graves de las leyes y usos aplicables en los conflictos armados internacionales (señale la INCORRECTA):',
 o: ['Dirigir intencionalmente ataques contra bienes que sean objetivos militares.', 'Dirigir intencionalmente ataques contra la población civil en cuanto tal o contra personas civiles que no participen directamente en las hostilidades.', 'Dirigir intencionalmente ataques contra bienes civiles, es decir, bienes que no son objetivos militares.', 'Atacar o bombardear, por cualquier medio, ciudades, aldeas, viviendas o edificios que no estén defendidos y que no sean objetivos militares.'],
 t: 'ii) Dirigir intencionalmente ataques contra bienes civiles, es decir, bienes que no son objetivos militares', p: 'Lo prohibido es atacar bienes civiles, no los objetivos militares.'},
{a: 'art. 8.2.b.iv)', r: 'Artículo 8. Crímenes de guerra', e: 'Lanzar un ataque intencionalmente, a sabiendas de que causará pérdidas incidentales de vidas, lesiones a civiles o daños a bienes de carácter civil o daños extensos, duraderos y graves al medio ambiente natural que serían manifiestamente excesivos en relación con:',
 o: ['la ventaja militar concreta y directa de conjunto que se prevea.', 'la ventaja militar directa e inmediata que se prevea.', 'el objetivo militar que se pretenda alcanzar.', 'la ventaja estratégica concreta y directa de conjunto que se prevea.'],
 t: 'que serían manifiestamente excesivos en relación con la ventaja militar concreta y directa de conjunto que se prevea', p: 'La fórmula literal es «ventaja militar concreta y directa de conjunto».'},
{a: 'art. 8.2.b.vi) y vii)', r: 'Artículo 8. Crímenes de guerra', e: 'Constituye crimen de guerra causar la muerte o lesiones a un combatiente que haya depuesto las armas o que, al no tener medios para defenderse, se haya rendido a discreción. Asimismo, constituye crimen de guerra:',
 o: ['utilizar de modo indebido la bandera blanca, la bandera nacional, las insignias militares o el uniforme del enemigo o de las Naciones Unidas, y causar así la muerte o lesiones graves.', 'utilizar de modo indebido la bandera blanca o los emblemas de los Convenios de Ginebra, aunque no se causen la muerte ni lesiones graves.', 'utilizar el uniforme del enemigo como estratagema de guerra, causando o no la muerte o lesiones.', 'utilizar la bandera nacional del enemigo en operaciones de reconocimiento.'],
 t: 'vii) Utilizar de modo indebido la bandera blanca, la bandera nacional o las insignias militares o el uniforme del enemigo o de las Naciones Unidas, así como los emblemas distintivos de los Convenios de Ginebra, y causar así la muerte o lesiones graves', p: 'El delito exige causar la muerte o lesiones graves.'},
{a: 'art. 8.2.b.viii)', r: 'Artículo 8. Crímenes de guerra', e: 'El traslado, directa o indirectamente, por la Potencia ocupante de parte de su población civil al territorio que ocupa o la deportación o el traslado de la totalidad o parte de la población del territorio ocupado, dentro o fuera de ese territorio, constituye:',
 o: ['una violación grave de las leyes y usos aplicables en los conflictos armados internacionales.', 'una infracción grave de los Convenios de Ginebra de 12 de agosto de 1949.', 'una violación grave del artículo 3 común a los cuatro Convenios de Ginebra.', 'un crimen de lesa humanidad por deportación o traslado forzoso.'],
 t: 'b) Otras violaciones graves de las leyes y usos aplicables en los conflictos armados internacionales dentro del marco establecido de derecho internacional, a saber, cualquiera de los actos siguientes: [...] viii) El traslado, directa o indirectamente, por la Potencia ocupante de parte de su población civil al territorio que ocupa', p: 'Está en el apartado b) del art. 8.2.'},
{a: 'art. 8.2.b.xxvi)', r: 'Artículo 8. Crímenes de guerra', e: 'Reclutar o alistar a niños menores de __________ años en las fuerzas armadas nacionales o utilizarlos para participar activamente en las hostilidades constituye un crimen de guerra en conflictos armados internacionales.',
 o: ['quince', 'dieciséis', 'dieciocho', 'catorce'],
 t: 'xxvi) Reclutar o alistar a niños menores de quince años en las fuerzas armadas nacionales o utilizarlos para participar activamente en las hostilidades', p: 'El umbral es de quince años.'},
{a: 'art. 8.2.b.xx)', r: 'Artículo 8. Crímenes de guerra', e: 'Emplear armas, proyectiles, materiales y métodos de guerra que, por su propia naturaleza, causen daños superfluos o sufrimientos innecesarios o surtan efectos indiscriminados en violación del derecho internacional de los conflictos armados constituye crimen de guerra, a condición de que esas armas sean:',
 o: ['objeto de una prohibición completa y estén incluidos en un anexo del Estatuto en virtud de una enmienda aprobada de conformidad con los artículos 121 y 123.', 'objeto de una prohibición parcial y estén incluidos en un anexo del Estatuto en virtud de una enmienda aprobada de conformidad con los artículos 121 y 123.', 'objeto de una prohibición completa y estén incluidos en un tratado ratificado por la mayoría de los Estados Partes.', 'objeto de una prohibición completa aprobada por el Consejo de Seguridad conforme al Capítulo VII de la Carta.'],
 t: 'a condición de que esas armas o esos proyectiles, materiales o métodos de guerra, sean objeto de una prohibición completa y estén incluidos en un anexo del presente Estatuto en virtud de una enmienda aprobada de conformidad con las disposiciones que, sobre el particular, figuran en los artículos 121 y 123', p: 'Se exige prohibición completa y anexo al Estatuto por enmienda.'},
{a: 'art. 8.2.c)', r: 'Artículo 8. Crímenes de guerra', e: 'En caso de conflicto armado que no sea de índole internacional, constituyen crímenes de guerra las violaciones graves del artículo 3 común a los cuatro Convenios de Ginebra de 12 de agosto de 1949, a saber, cualquiera de los siguientes actos cometidos contra personas que no participen directamente en las hostilidades (señale la INCORRECTA):',
 o: ['Los ataques contra bienes civiles que no sean objetivos militares.', 'Los atentados contra la vida y la integridad corporal, especialmente el homicidio en todas sus formas, las mutilaciones, los tratos crueles y la tortura.', 'Los ultrajes contra la dignidad personal, especialmente los tratos humillantes y degradantes.', 'La toma de rehenes.'],
 t: 'i) Los atentados contra la vida y la integridad corporal, especialmente el homicidio en todas sus formas, las mutilaciones, los tratos crueles y la tortura; ii) Los ultrajes contra la dignidad personal, especialmente los tratos humillantes y degradantes; iii) La toma de rehenes; iv) Las condenas dictadas y las ejecuciones sin previo juicio ante un tribunal regularmente constituido', p: 'Los ataques contra bienes civiles no figuran en el art. 8.2.c).'},
{a: 'art. 8.2.d) y 8.2.f)', r: 'Artículo 8. Crímenes de guerra', e: 'El párrafo 2.c) del artículo 8 se aplica a los conflictos armados que no son de índole internacional y, por consiguiente, no se aplica a las situaciones de tensiones internas y de disturbios interiores, tales como:',
 o: ['los motines, los actos esporádicos y aislados de violencia u otros actos análogos.', 'los motines, los golpes de Estado y los actos terroristas aislados.', 'las revueltas, las insurrecciones y los actos esporádicos de violencia.', 'los motines y las insurrecciones armadas contra el Gobierno.'],
 t: 'El párrafo 2.c) del presente artículo se aplica a los conflictos armados que no son de índole internacional, y por consiguiente, no se aplica a las situaciones de tensiones internas y de disturbios interiores, tales como los motines, los actos esporádicos y aislados de violencia u otros actos análogos', p: 'Quedan fuera los motines, los actos esporádicos y aislados de violencia y los análogos.'},
{a: 'art. 8.2.e)', r: 'Artículo 8. Crímenes de guerra', e: 'En los conflictos armados que no sean de índole internacional, constituyen otras violaciones graves de las leyes y los usos aplicables (señale la INCORRECTA):',
 o: ['Reclutar o alistar niños menores de dieciocho años en las fuerzas armadas o grupos.', 'Saquear una ciudad o plaza, incluso cuando es tomada por asalto.', 'Declarar que no se dará cuartel.', 'Matar o herir a traición a un combatiente adversario.'],
 t: 'vii) Reclutar o alistar niños menores de quince años en las fuerzas armadas o grupos o utilizarlos para participar activamente en hostilidades', p: 'El umbral es el de quince años, también en los conflictos no internacionales.'},
{a: 'art. 8.2.f)', r: 'Artículo 8. Crímenes de guerra', e: 'El párrafo 2.e) del artículo 8 se aplica a los conflictos armados que no son de índole internacional. Se aplica a los conflictos armados que tienen lugar en el territorio de un Estado cuando existe:',
 o: ['un conflicto armado prolongado entre las autoridades gubernamentales y grupos armados organizados o entre tales grupos.', 'un conflicto armado entre las autoridades gubernamentales y grupos armados organizados, cualquiera que sea su duración.', 'un conflicto armado prolongado entre dos o más Estados vecinos.', 'una situación de tensiones internas prolongada entre grupos armados organizados.'],
 t: 'Se aplica a los conflictos armados que tienen lugar en el territorio de un Estado cuando existe un conflicto armado prolongado entre las autoridades gubernamentales y grupos armados organizados o entre tales grupos', p: 'Se exige un conflicto armado prolongado entre autoridades gubernamentales y grupos armados organizados, o entre estos grupos.'},
{a: 'art. 8.3', r: 'Artículo 8. Crímenes de guerra', e: 'Nada de lo dispuesto en los párrafos 2.c) y e) afectará a la responsabilidad que incumbe a todo gobierno de mantener o restablecer el orden público en el Estado o de defender la unidad e integridad territorial del Estado:',
 o: ['por cualquier medio legítimo.', 'por todos los medios necesarios.', 'por cualquier medio lícito y proporcionado.', 'con arreglo a la legislación del Estado.'],
 t: 'Nada de lo dispuesto en los párrafos 2.c) y e) afectará a la responsabilidad que incumbe a todo gobierno de mantener o restablecer el orden público en el Estado o de defender la unidad e integridad territorial del Estado por cualquier medio legítimo', p: 'Se dice «por cualquier medio legítimo».'},
// ── Art. 8 bis ──
{a: 'art. 8 bis.1', r: 'Artículo 8 bis. Crimen de agresión', e: 'Una persona comete un «crimen de agresión» cuando, estando en condiciones de controlar o dirigir efectivamente la acción política o militar de un Estado, dicha persona planifica, prepara, inicia o realiza un acto de agresión que por sus características, gravedad y escala constituya:',
 o: ['una violación manifiesta de la Carta de las Naciones Unidas.', 'una violación grave de la Carta de las Naciones Unidas.', 'una violación manifiesta del derecho internacional humanitario.', 'una infracción grave de los Convenios de Ginebra.'],
 t: 'planifica, prepara, inicia o realiza un acto de agresión que por sus características, gravedad y escala constituya una violación manifiesta de la Carta de las Naciones Unidas', p: 'Se exige una violación «manifiesta» de la Carta de las Naciones Unidas.'},
{a: 'art. 8 bis.2', r: 'Artículo 8 bis. Crimen de agresión', e: 'Se entenderá por «acto de agresión» el uso de la fuerza armada por un Estado contra la soberanía, la integridad territorial o la independencia política de otro Estado. De conformidad con la resolución 3314 (XXIX) de la Asamblea General de las Naciones Unidas, de 14 de diciembre de 1974, cualquiera de los actos siguientes se caracterizará como acto de agresión, independientemente de:',
 o: ['que haya o no declaración de guerra.', 'que haya o no autorización del Consejo de Seguridad.', 'que haya o no víctimas civiles.', 'que se cometa o no contra un Estado Parte en el Estatuto.'],
 t: 'cualquiera de los actos siguientes, independientemente de que haya o no declaración de guerra, se caracterizará como acto de agresión', p: 'Es irrelevante que haya o no declaración de guerra.'},
{a: 'art. 8 bis.2', r: 'Artículo 8 bis. Crimen de agresión', e: 'Se caracterizará como acto de agresión (señale la INCORRECTA):',
 o: ['La acción de un Estado que permite que su territorio, puesto a disposición de otro Estado, sea utilizado para cometer una agresión, aunque no se perpetre el acto contra un tercer Estado.', 'La invasión o el ataque por las fuerzas armadas de un Estado del territorio de otro Estado, o toda ocupación militar, aún temporal, que resulte de dicha invasión o ataque.', 'El bloqueo de los puertos o de las costas de un Estado por las fuerzas armadas de otro Estado.', 'El bombardeo, por las fuerzas armadas de un Estado, del territorio de otro Estado, o el empleo de cualesquiera armas por un Estado contra el territorio de otro Estado.'],
 t: 'f) La acción de un Estado que permite que su territorio, que ha puesto a disposición de otro Estado, sea utilizado por ese otro Estado para perpetrar un acto de agresión contra un tercer Estado', p: 'Se exige que el otro Estado utilice el territorio «para perpetrar un acto de agresión contra un tercer Estado».'},
// ── Art. 9 a 12 ──
{a: 'art. 9.1', r: 'Artículo 9. Elementos de los crímenes', e: 'Los Elementos de los Crímenes ayudarán a la Corte a interpretar y aplicar los artículos 6, 7, 8 y 8 bis del Estatuto, y serán aprobados por una mayoría de __________ de los miembros de la Asamblea de los Estados Partes.',
 o: ['dos tercios', 'tres cuartos', 'mayoría absoluta', 'tres quintos'],
 t: 'Los Elementos de los Crímenes ayudarán a la Corte a interpretar y aplicar los artículos 6, 7, 8 y 8 bis del presente Estatuto, serán aprobados por una mayoría de dos tercios de los miembros de la Asamblea de los Estados Partes', p: 'Mayoría de dos tercios de los miembros de la Asamblea.'},
{a: 'art. 9.2', r: 'Artículo 9. Elementos de los crímenes', e: 'Podrán proponer enmiendas a los Elementos de los crímenes (señale la INCORRECTA):',
 o: ['Los magistrados, por mayoría simple.', 'Cualquier Estado Parte.', 'Los magistrados, por mayoría absoluta.', 'El fiscal.'],
 t: 'Podrán proponer enmiendas a los Elementos de los crímenes: a) Cualquier Estado Parte; b) Los magistrados, por mayoría absoluta; c) El fiscal', p: 'Los magistrados proponen por mayoría absoluta, no simple.'},
{a: 'art. 9.3', r: 'Artículo 9. Elementos de los crímenes', e: 'Los Elementos de los crímenes y sus enmiendas serán compatibles con lo dispuesto:',
 o: ['en el presente Estatuto.', 'en el presente Estatuto y en las Reglas de Procedimiento y Prueba.', 'en el Derecho internacional humanitario.', 'en los Convenios de Ginebra de 12 de agosto de 1949.'],
 t: 'Los Elementos de los crímenes y sus enmiendas serán compatibles con lo dispuesto en el presente Estatuto', p: 'Han de ser compatibles con el Estatuto.'},
{a: 'art. 11', r: 'Artículo 11. Competencia temporal', e: 'La Corte tendrá competencia únicamente respecto de crímenes cometidos después de la entrada en vigor del Estatuto. Si un Estado se hace Parte en el Estatuto después de su entrada en vigor, la Corte podrá ejercer su competencia únicamente con respecto a los crímenes cometidos después de la entrada en vigor del Estatuto respecto de ese Estado, a menos que éste:',
 o: ['haya hecho una declaración de conformidad con el párrafo 3 del artículo 12.', 'haya hecho una declaración de conformidad con el párrafo 2 del artículo 12.', 'haya sido instado a hacerlo por el Consejo de Seguridad.', 'haya autorizado expresamente a la Corte mediante un acuerdo bilateral.'],
 t: 'a menos que éste haya hecho una declaración de conformidad con el párrafo 3 del artículo 12', p: 'La excepción es la declaración del art. 12.3.'},
{a: 'art. 12.1', r: 'Artículo 12. Condiciones previas para el ejercicio de la competencia', e: 'El Estado que pase a ser Parte en el Estatuto acepta por ello la competencia de la Corte respecto a los crímenes a que se refiere:',
 o: ['el artículo 5.', 'el artículo 6.', 'el artículo 13.', 'el artículo 8.'],
 t: 'El Estado que pase a ser Parte en el presente Estatuto acepta por ello la competencia de la Corte [...] a los crímenes a que se refiere el artículo 5', p: 'La aceptación abarca los crímenes del art. 5.'},
{a: 'art. 12.2', r: 'Artículo 12. Condiciones previas para el ejercicio de la competencia', e: 'En el caso de los apartados a) o c) del artículo 13, la Corte podrá ejercer su competencia si uno o varios de los Estados siguientes son Partes en el Estatuto o han aceptado la competencia de la Corte (señale la INCORRECTA):',
 o: ['El Estado en cuyo territorio se encuentre detenido el acusado.', 'El Estado en cuyo territorio haya tenido lugar la conducta de que se trate.', 'El Estado de matrícula del buque o la aeronave, si el crimen se hubiere cometido a bordo de ellos.', 'El Estado del que sea nacional el acusado del crimen.'],
 t: 'a) El Estado en cuyo territorio haya tenido lugar la conducta de que se trate, o si el crimen se hubiere cometido a bordo de un buque o de una aeronave, el Estado de matrícula del buque o la aeronave; b) El Estado del que sea nacional el acusado del crimen', p: 'El Estado de detención no figura entre los vinculados.'},
{a: 'art. 12.3', r: 'Artículo 12. Condiciones previas para el ejercicio de la competencia', e: 'Si la aceptación de un Estado que no sea Parte en el Estatuto fuere necesaria, dicho Estado podrá, mediante declaración depositada en poder del secretario, consentir en que la Corte ejerza su competencia respecto del crimen de que se trate. El Estado aceptante cooperará con la Corte:',
 o: ['sin demora ni excepción de conformidad con la Parte IX.', 'sin demora, con sujeción a las excepciones de la Parte IX.', 'en la medida de sus posibilidades, de conformidad con la Parte IX.', 'sin demora ni excepción de conformidad con la Parte V.'],
 t: 'El Estado aceptante cooperará con la Corte sin demora ni excepción de conformidad con la Parte IX', p: 'La cooperación es «sin demora ni excepción», conforme a la Parte IX.'},
// ── Art. 13 a 15 ──
{a: 'art. 13', r: 'Artículo 13. Ejercicio de la competencia', e: 'La Corte podrá ejercer su competencia respecto de cualquiera de los crímenes a que se refiere el artículo 5 si (señale la INCORRECTA):',
 o: ['La Asamblea de los Estados Partes remite al fiscal una situación en que parezca haberse cometido uno o varios de esos crímenes.', 'Un Estado Parte remite al fiscal una situación en que parezca haberse cometido uno o varios de esos crímenes.', 'El Consejo de Seguridad, actuando con arreglo a lo dispuesto en el Capítulo VII de la Carta de las Naciones Unidas, remite al fiscal una situación en que parezca haberse cometido uno o varios de esos crímenes.', 'El fiscal ha iniciado una investigación respecto de un crimen de ese tipo.'],
 t: 'a) Un Estado Parte remite al fiscal, de conformidad con el artículo 14, una situación en que parezca haberse cometido uno o varios de esos crímenes; b) El Consejo de Seguridad, actuando con arreglo a lo dispuesto en el Capítulo VII de la Carta de las Naciones Unidas, remite al fiscal una situación en que parezca haberse cometido uno o varios de esos crímenes; o c) El fiscal ha iniciado una investigación respecto de un crimen de ese tipo', p: 'Solo hay tres vías: Estado Parte, Consejo de Seguridad y fiscal; la Asamblea no remite situaciones.'},
{a: 'art. 14', r: 'Artículo 14. Remisión de una situación por un Estado Parte', e: 'En la medida de lo posible, en la remisión se especificarán las circunstancias pertinentes y se adjuntará:',
 o: ['la documentación justificativa de que disponga el Estado denunciante.', 'la documentación justificativa exigida por la Sala de Cuestiones Preliminares.', 'un resumen de las pruebas que posea el Estado denunciante.', 'la documentación justificativa que determine el fiscal.'],
 t: 'En la medida de lo posible, en la remisión se especificarán las circunstancias pertinentes y se adjuntará la documentación justificativa de que disponga el Estado denunciante', p: 'Se adjunta la documentación de que disponga el Estado denunciante.'},
{a: 'art. 15.1 y 15.2', r: 'Artículo 15. El fiscal', e: 'El fiscal podrá iniciar de oficio una investigación sobre la base de información acerca de un crimen de la competencia de la Corte. El fiscal analizará la veracidad de la información recibida. Con tal fin, podrá recabar más información de los Estados, los órganos de las Naciones Unidas, las organizaciones intergubernamentales o no gubernamentales u otras fuentes fidedignas que considere apropiadas y podrá recibir testimonios escritos y orales:',
 o: ['en la sede de la Corte.', 'en cualquier lugar que considere apropiado.', 'en la sede de la Corte o en la del Estado interesado.', 'ante la Sala de Cuestiones Preliminares.'],
 t: 'podrá recabar más información de los Estados, los órganos de la Naciones Unidas, las organizaciones intergubernamentales o no gubernamentales u otras fuentes fidedignas que considere apropiadas y podrá recibir testimonios escritos y orales en la sede de la Corte', p: 'Los testimonios se reciben en la sede de la Corte.'},
{a: 'art. 15.3', r: 'Artículo 15. El fiscal', e: 'El fiscal, si llegare a la conclusión de que existe fundamento suficiente para abrir una investigación, presentará a la Sala de Cuestiones Preliminares una petición de autorización para ello, junto con la documentación justificativa que haya reunido. Las víctimas podrán:',
 o: ['presentar observaciones a la Sala de Cuestiones Preliminares, de conformidad con las Reglas de Procedimiento y Prueba.', 'presentar sus propias peticiones de investigación ante la Sala de Cuestiones Preliminares.', 'presentar observaciones al fiscal, de conformidad con las Reglas de Procedimiento y Prueba.', 'solicitar la autorización de la investigación ante la Presidencia de la Corte.'],
 t: 'Las víctimas podrán presentar observaciones a la Sala de Cuestiones Preliminares, de conformidad con las Reglas de Procedimiento y Prueba', p: 'Las observaciones se presentan a la Sala de Cuestiones Preliminares.'},
{a: 'art. 15.4 y 15.5', r: 'Artículo 15. El fiscal', e: 'La negativa de la Sala de Cuestiones Preliminares a autorizar la investigación no impedirá que el fiscal presente ulteriormente otra petición basada en:',
 o: ['nuevos hechos o pruebas relacionadas con la misma situación.', 'nuevos hechos o pruebas relacionadas con otra situación.', 'nuevos fundamentos jurídicos relacionados con la misma situación.', 'la autorización expresa del Consejo de Seguridad.'],
 t: 'La negativa de la Sala de Cuestiones Preliminares a autorizar la investigación no impedirá que el fiscal presente ulteriormente otra petición basada en nuevos hechos o pruebas relacionadas con la misma situación', p: 'Se exigen nuevos hechos o pruebas de la misma situación.'},
{a: 'art. 15.6', r: 'Artículo 15. El fiscal', e: 'Si, después del examen preliminar, el fiscal llega a la conclusión de que la información presentada no constituye fundamento suficiente para una investigación, informará de ello a quienes la hubieren presentado. Ello no impedirá que el fiscal examine, a la luz de hechos o pruebas nuevos, otra información que reciba:',
 o: ['en relación con la misma situación.', 'en relación con cualquier situación.', 'en relación con el mismo crimen y distintos autores.', 'con autorización de la Sala de Cuestiones Preliminares.'],
 t: 'Ello no impedirá que el fiscal examine, a la luz de hechos o pruebas nuevos, otra información que reciba en relación con la misma situación', p: 'Se refiere a otra información sobre la misma situación.'},
// ── Art. 15 bis y 15 ter ──
{a: 'art. 15 bis.2', r: 'Artículo 15 bis. Ejercicio de la competencia respecto del crimen de agresión (remisión por un Estado, proprio motu)', e: 'La Corte únicamente podrá ejercer su competencia respecto de crímenes de agresión cometidos un año después de la ratificación o aceptación de las enmiendas por:',
 o: ['treinta Estados Partes.', 'veinte Estados Partes.', 'dos tercios de los Estados Partes.', 'cuarenta Estados Partes.'],
 t: 'La Corte únicamente podrá ejercer su competencia respecto de crímenes de agresión cometidos un año después de la ratificación o aceptación de las enmiendas por treinta Estados Partes', p: 'Treinta Estados Partes, un año después.'},
{a: 'art. 15 bis.3', r: 'Artículo 15 bis. Ejercicio de la competencia respecto del crimen de agresión (remisión por un Estado, proprio motu)', e: 'La Corte ejercerá su competencia respecto del crimen de agresión a condición de que se adopte una decisión después del 1° de enero de 2017 por:',
 o: ['la misma mayoría de Estados Partes que se requiere para la aprobación de una enmienda al Estatuto.', 'la mayoría absoluta de los Estados Partes en el Estatuto.', 'la unanimidad de los Estados Partes que hayan ratificado las enmiendas.', 'el Consejo de Seguridad por mayoría de nueve de sus miembros.'],
 t: 'a condición de que se adopte una decisión después del 1° de enero de 2017 por la misma mayoría de Estados Partes que se requiere para la aprobación de una enmienda al Estatuto', p: 'La misma mayoría que para aprobar una enmienda al Estatuto (dos tercios).'},
{a: 'art. 15 bis.4', r: 'Artículo 15 bis. Ejercicio de la competencia respecto del crimen de agresión (remisión por un Estado, proprio motu)', e: 'La Corte podrá ejercer su competencia sobre un crimen de agresión resultante de un acto de agresión cometido por un Estado Parte, salvo que ese Estado Parte haya declarado previamente que no acepta esa competencia mediante el depósito de una declaración en poder del Secretario. La retirada de esa declaración podrá efectuarse en cualquier momento y será considerada por el Estado Parte en un plazo de:',
 o: ['tres años.', 'un año.', 'seis meses.', 'cinco años.'],
 t: 'La retirada de esa declaración podrá efectuarse en cualquier momento y será considerada por el Estado Parte en un plazo de tres años', p: 'El plazo es de tres años.'},
{a: 'art. 15 bis.5', r: 'Artículo 15 bis. Ejercicio de la competencia respecto del crimen de agresión (remisión por un Estado, proprio motu)', e: 'Respecto de un Estado no Parte en el Estatuto, la Corte no ejercerá su competencia respecto del crimen de agresión cuando éste sea cometido:',
 o: ['por los nacionales de ese Estado o en el territorio del mismo.', 'por los nacionales de ese Estado, aunque sea en el territorio de un Estado Parte.', 'en el territorio de ese Estado, aunque sea por nacionales de un Estado Parte.', 'por los nacionales de ese Estado, salvo que el Consejo de Seguridad lo remita.'],
 t: 'Respecto de un Estado no Parte en el presente Estatuto, la Corte no ejercerá su competencia respecto del crimen de agresión cuando éste sea cometido por los nacionales de ese Estado o en el territorio del mismo', p: 'Quedan fuera tanto los nacionales como el territorio del Estado no Parte.'},
{a: 'art. 15 bis.6 a 15 bis.8', r: 'Artículo 15 bis. Ejercicio de la competencia respecto del crimen de agresión (remisión por un Estado, proprio motu)', e: 'Cuando no se realice la determinación por el Consejo de Seguridad de que ha habido un acto de agresión en el plazo de __________ desde la fecha de notificación, el Fiscal podrá iniciar los procedimientos de investigación respecto de un crimen de agresión, siempre que la Sección de Cuestiones Preliminares haya autorizado el inicio de la investigación.',
 o: ['seis meses', 'tres meses', 'doce meses', 'un mes'],
 t: 'Cuando no se realice dicha determinación en el plazo de seis meses desde la fecha de notificación, el Fiscal podrá iniciar los procedimientos de investigación respecto de un crimen de agresión', p: 'El plazo es de seis meses.'},
{a: 'art. 15 bis.6', r: 'Artículo 15 bis. Ejercicio de la competencia respecto del crimen de agresión (remisión por un Estado, proprio motu)', e: 'El Fiscal, si llegare a la conclusión de que existe fundamento razonable para iniciar una investigación sobre un crimen de agresión, verificará en primer lugar si el Consejo de Seguridad ha determinado la existencia de un acto de agresión cometido por el Estado de que se trate. El Fiscal notificará:',
 o: ['al Secretario General de las Naciones Unidas la situación ante la Corte, adjuntando la documentación y otros antecedentes que sean pertinentes.', 'al Presidente del Consejo de Seguridad la situación ante la Corte, adjuntando la documentación que sea pertinente.', 'a la Asamblea de los Estados Partes la situación ante la Corte, adjuntando los antecedentes pertinentes.', 'a la Sala de Cuestiones Preliminares la situación ante la Corte, adjuntando los antecedentes pertinentes.'],
 t: 'El Fiscal notificará al Secretario General de las Naciones Unidas la situación ante la Corte, adjuntando la documentación y otros antecedentes que sean pertinentes', p: 'La notificación se dirige al Secretario General de las Naciones Unidas.'},
{a: 'art. 15 ter.2', r: 'Artículo 15 ter. Ejercicio de la competencia respecto del crimen de agresión (remisión por el Consejo de Seguridad)', e: 'La Corte podrá ejercer su competencia respecto del crimen de agresión de conformidad con el apartado b) del artículo 13, esto es, cuando el asunto haya sido remitido por:',
 o: ['el Consejo de Seguridad.', 'un Estado Parte.', 'el fiscal de oficio.', 'la Asamblea de los Estados Partes.'],
 t: 'La Corte podrá ejercer su competencia respecto del crimen de agresión de conformidad con el apartado b) del artículo 13, con sujeción a las disposiciones de este artículo', p: 'El apartado b) del art. 13 es la remisión por el Consejo de Seguridad.'},
// ── Art. 16 a 21 ──
{a: 'art. 16', r: 'Artículo 16. Suspensión de la investigación o el enjuiciamiento', e: 'En caso de que el Consejo de Seguridad, de conformidad con una resolución aprobada con arreglo a lo dispuesto en el Capítulo VII de la Carta de las Naciones Unidas, pida a la Corte que no inicie o que suspenda por un plazo de __________ la investigación o el enjuiciamiento que haya iniciado, la Corte procederá a esa suspensión; la petición podrá ser renovada por el Consejo de Seguridad en las mismas condiciones.',
 o: ['doce meses', 'seis meses', 'veinticuatro meses', 'tres meses'],
 t: 'pida a la Corte que no inicie o que suspenda por un plazo de doce meses la investigación o el enjuiciamiento que haya iniciado, la Corte procederá a esa suspensión; la petición podrá ser renovada por el Consejo de Seguridad en las mismas condiciones', p: 'La suspensión es por doce meses, renovable.'},
{a: 'art. 17.1', r: 'Artículo 17. Cuestiones de admisibilidad', e: 'La Corte resolverá la inadmisibilidad de un asunto cuando (señale la INCORRECTA):',
 o: ['El asunto sea objeto de una investigación por un Estado que tenga jurisdicción sobre él, aunque éste no esté dispuesto a llevarla a cabo.', 'El asunto no sea de gravedad suficiente para justificar la adopción de otras medidas por la Corte.', 'La persona de que se trate haya sido ya enjuiciada por la conducta a que se refiere la denuncia, y la Corte no pueda adelantar el juicio con arreglo al párrafo 3 del artículo 20.', 'El asunto haya sido objeto de investigación por un Estado que tenga jurisdicción sobre él y éste haya decidido no incoar acción penal, salvo que la decisión haya obedecido a que no esté dispuesto a llevar a cabo el enjuiciamiento o no pueda realmente hacerlo.'],
 t: 'a) El asunto sea objeto de una investigación o enjuiciamiento por un Estado que tenga jurisdicción sobre él, salvo que éste no esté dispuesto a llevar a cabo la investigación o el enjuiciamiento o no pueda realmente hacerlo', p: 'Si el Estado no está dispuesto o no puede realmente investigar, el asunto sí es admisible.'},
{a: 'art. 17.2', r: 'Artículo 17. Cuestiones de admisibilidad', e: 'A fin de determinar si hay o no disposición a actuar en un asunto determinado, la Corte examinará, teniendo en cuenta los principios de un proceso con las debidas garantías reconocidos por el derecho internacional, si se da una o varias de las siguientes circunstancias (señale la INCORRECTA):',
 o: ['Que el Estado haya ratificado todos los Convenios de Ginebra de 12 de agosto de 1949.', 'Que el juicio ya haya estado o esté en marcha o que la decisión nacional haya sido adoptada con el propósito de sustraer a la persona de su responsabilidad penal por crímenes de la competencia de la Corte.', 'Que haya habido una demora injustificada en el juicio que, dadas las circunstancias, sea incompatible con la intención de hacer comparecer a la persona ante la justicia.', 'Que el proceso no haya sido o no esté siendo sustanciado de manera independiente o imparcial.'],
 t: 'a) Que el juicio ya haya estado o esté en marcha o que la decisión nacional haya sido adoptada con el propósito de sustraer a la persona de que se trate de su responsabilidad penal por crímenes de la competencia de la Corte, según lo dispuesto en el artículo 5; b) Que haya habido una demora injustificada en el juicio que, dadas las circunstancias, sea incompatible con la intención de hacer comparecer a la persona de que se trate ante la justicia', p: 'La ratificación de los Convenios de Ginebra no es una de las circunstancias.'},
{a: 'art. 17.3', r: 'Artículo 17. Cuestiones de admisibilidad', e: 'A fin de determinar la incapacidad para investigar o enjuiciar en un asunto determinado, la Corte examinará si el Estado, debido al colapso total o sustancial de su administración nacional de justicia o al hecho de que carece de ella, no puede hacer comparecer al acusado, no dispone de las pruebas y los testimonios necesarios o:',
 o: ['no está por otras razones en condiciones de llevar a cabo el juicio.', 'no cuenta con los recursos materiales para llevar a cabo el juicio.', 'no ha tipificado en su legislación los crímenes de la competencia de la Corte.', 'no está en condiciones de proteger a las víctimas y a los testigos.'],
 t: 'no puede hacer comparecer al acusado, no dispone de las pruebas y los testimonios necesarios o no está por otras razones en condiciones de llevar a cabo el juicio', p: 'La cláusula final es «no está por otras razones en condiciones de llevar a cabo el juicio».'},
{a: 'art. 18.1', r: 'Artículo 18. Decisiones preliminares relativas a la admisibilidad', e: 'Cuando se haya remitido a la Corte una situación en virtud del artículo 13.a) y el fiscal haya determinado que existen fundamentos razonables para comenzar una investigación, o el fiscal inicie una investigación en virtud de los artículos 13.c) y 15, éste lo notificará:',
 o: ['a todos los Estados Partes y a aquellos Estados que, teniendo en cuenta la información disponible, ejercerían normalmente la jurisdicción sobre los crímenes de que se trate.', 'a todos los Estados Partes y al Consejo de Seguridad de las Naciones Unidas.', 'únicamente a los Estados que, teniendo en cuenta la información disponible, ejercerían normalmente la jurisdicción sobre los crímenes de que se trate.', 'a la Sala de Cuestiones Preliminares y a los Estados que hayan remitido la situación.'],
 t: 'éste lo notificará a todos los Estados Partes y a aquellos Estados que, teniendo en cuenta la información disponible, ejercerían normalmente la jurisdicción sobre los crímenes de que se trate', p: 'La notificación es a todos los Estados Partes y a los que ejercerían normalmente la jurisdicción.'},
{a: 'art. 18.2', r: 'Artículo 18. Decisiones preliminares relativas a la admisibilidad', e: 'Dentro del __________ siguiente a la recepción de dicha notificación, el Estado podrá informar a la Corte que está llevando o ha llevado a cabo una investigación en relación con sus nacionales u otras personas bajo su jurisdicción. A petición de dicho Estado, el fiscal se inhibirá de su competencia en favor del Estado, a menos que la Sala de Cuestiones Preliminares decida, a petición del fiscal, autorizar la investigación.',
 o: ['mes', 'plazo de quince días', 'plazo de tres meses', 'plazo de seis meses'],
 t: 'Dentro del mes siguiente a la recepción de dicha notificación, el Estado podrá informar a la Corte que está llevando o ha llevado a cabo una investigación en relación con sus nacionales u otras personas bajo su jurisdicción', p: 'El plazo es de un mes desde la notificación.'},
{a: 'art. 18.3', r: 'Artículo 18. Decisiones preliminares relativas a la admisibilidad', e: 'El fiscal podrá volver a examinar la cuestión de la inhibición de su competencia al cabo de __________ a partir de la fecha de la inhibición o cuando se haya producido un cambio significativo de circunstancias en vista de que el Estado no está dispuesto a llevar a cabo la investigación o no puede realmente hacerlo.',
 o: ['seis meses', 'un año', 'tres meses', 'dos años'],
 t: 'El fiscal podrá volver a examinar la cuestión de la inhibición de su competencia al cabo de seis meses a partir de la fecha de la inhibición o cuando se haya producido un cambio significativo de circunstancias', p: 'Seis meses desde la inhibición.'},
{a: 'art. 18.4', r: 'Artículo 18. Decisiones preliminares relativas a la admisibilidad', e: 'El Estado de que se trate o el fiscal podrán apelar ante la Sala de Apelaciones de la decisión de la Sala de Cuestiones Preliminares, de conformidad con lo dispuesto en el artículo 82. La apelación podrá sustanciarse:',
 o: ['en forma sumaria.', 'en procedimiento ordinario.', 'ante la Sala de Primera Instancia.', 'con efecto suspensivo.'],
 t: 'El Estado de que se trate o el fiscal podrán apelar ante la Sala de Apelaciones de la decisión de la Sala de Cuestiones Preliminares, de conformidad con lo dispuesto en el artículo 82. La apelación podrá sustanciarse en forma sumaria', p: 'La apelación puede tramitarse en forma sumaria.'},
{a: 'art. 18.6', r: 'Artículo 18. Decisiones preliminares relativas a la admisibilidad', e: 'El fiscal podrá, hasta que la Sala de Cuestiones Preliminares haya emitido su decisión, o en cualquier momento si se hubiere inhibido de su competencia, pedir a la Sala de Cuestiones Preliminares, con carácter excepcional, que le autorice a llevar adelante las indagaciones que estime necesarias cuando:',
 o: ['exista una oportunidad única de obtener pruebas importantes o exista un riesgo significativo de que esas pruebas no estén disponibles ulteriormente.', 'exista una oportunidad única de obtener pruebas importantes y un riesgo grave de que desaparezcan.', 'el Estado que haya ejercido la jurisdicción lo solicite expresamente a la Corte.', 'las pruebas se encuentren en el territorio de un Estado que no sea parte en el Estatuto.'],
 t: 'cuando exista una oportunidad única de obtener pruebas importantes o exista un riesgo significativo de que esas pruebas no estén disponibles ulteriormente', p: 'Basta una oportunidad única «o» un riesgo significativo.'},
{a: 'art. 19.1 y 19.2', r: 'Artículo 19. Impugnación de la competencia de la Corte o de la admisibilidad de la causa', e: 'Podrán impugnar la admisibilidad de la causa, por uno de los motivos mencionados en el artículo 17, o impugnar la competencia de la Corte (señale la INCORRECTA):',
 o: ['La víctima del crimen.', 'El acusado o la persona contra la cual se haya dictado una orden de detención o una orden de comparecencia.', 'Un Estado que tenga jurisdicción en la causa porque está investigándola o enjuiciándola o lo ha hecho antes.', 'Un Estado cuya aceptación se requiera de conformidad con el artículo 12.'],
 t: 'a) El acusado o la persona contra la cual se haya dictado una orden de detención o una orden de comparecencia con arreglo al artículo 58; b) Un Estado que tenga jurisdicción en la causa porque está investigándola o enjuiciándola o lo ha hecho antes; o c) Un Estado cuya aceptación se requiera de conformidad con el artículo 12', p: 'Las víctimas pueden presentar observaciones (art. 19.3) pero no impugnar.'},
{a: 'art. 19.4', r: 'Artículo 19. Impugnación de la competencia de la Corte o de la admisibilidad de la causa', e: 'La admisibilidad de una causa o la competencia de la Corte sólo podrán ser impugnadas una sola vez. La impugnación se hará antes del juicio o a su inicio. En circunstancias excepcionales, la Corte podrá autorizar que la impugnación se haga más de una vez o en una fase ulterior del juicio. Las impugnaciones hechas al inicio del juicio, o posteriormente con la autorización de la Corte, sólo podrán fundarse en:',
 o: ['el párrafo 1.c) del artículo 17.', 'el párrafo 1.a) del artículo 17.', 'el párrafo 1.d) del artículo 17.', 'el párrafo 2 del artículo 17.'],
 t: 'Las impugnaciones o la admisibilidad de una causa hechas al inicio del juicio, o posteriormente con la autorización de la Corte, sólo podrán fundarse en el párrafo 1.c) del artículo 17', p: 'Solo la cosa juzgada (art. 17.1.c).'},
{a: 'art. 19.6', r: 'Artículo 19. Impugnación de la competencia de la Corte o de la admisibilidad de la causa', e: 'Antes de la confirmación de los cargos, la impugnación de la admisibilidad de una causa o de la competencia de la Corte será asignada a la Sala de Cuestiones Preliminares. Después de confirmados los cargos, será asignada a la Sala de Primera Instancia. Las decisiones relativas a la competencia o la admisibilidad podrán ser recurridas ante:',
 o: ['la Sala de Apelaciones.', 'la Sala de Primera Instancia.', 'la Presidencia de la Corte.', 'la Sala de Cuestiones Preliminares.'],
 t: 'Las decisiones relativas a la competencia o la admisibilidad podrán ser recurridas ante la Sala de Apelaciones de conformidad con el artículo 82', p: 'Se recurren ante la Sala de Apelaciones.'},
{a: 'art. 19.7', r: 'Artículo 19. Impugnación de la competencia de la Corte o de la admisibilidad de la causa', e: 'Si la impugnación es hecha por el Estado a que se hace referencia en los apartados b) o c) del párrafo 2, el fiscal:',
 o: ['suspenderá la investigación hasta que la Corte resuelva de conformidad con el artículo 17.', 'continuará la investigación hasta que la Corte resuelva de conformidad con el artículo 17.', 'suspenderá la investigación durante un plazo de seis meses.', 'suspenderá la investigación, salvo que la Sala de Cuestiones Preliminares decida lo contrario.'],
 t: 'Si la impugnación es hecha por el Estado a que se hace referencia en los apartados b) o c) del párrafo 2, el fiscal suspenderá la investigación hasta que la Corte resuelva de conformidad con el artículo 17', p: 'La suspensión dura hasta que la Corte resuelva.'},
{a: 'art. 19.8', r: 'Artículo 19. Impugnación de la competencia de la Corte o de la admisibilidad de la causa', e: 'Hasta antes de que la Corte se pronuncie sobre la impugnación, el fiscal podrá pedirle autorización para (señale la INCORRECTA):',
 o: ['Practicar nuevos allanamientos en el territorio del Estado que impugna.', 'Practicar las indagaciones necesarias de la índole mencionada en el párrafo 6 del artículo 18.', 'Tomar declaración a un testigo o recibir su testimonio, o completar la recolección y el examen de las pruebas que hubiere iniciado antes de la impugnación.', 'Impedir, en cooperación con los Estados que corresponda, que eludan la acción de la justicia personas respecto de los cuales el fiscal haya pedido ya una orden de detención.'],
 t: 'a) Practicar las indagaciones necesarias de la índole mencionada en el párrafo 6 del artículo 18; b) Tomar declaración a un testigo o recibir su testimonio, o completar la recolección y el examen de las pruebas que hubiere iniciado antes de la impugnación; y c) Impedir, en cooperación con los Estados que corresponda, que eludan la acción de la justicia personas respecto de los cuales el fiscal haya pedido ya una orden de detención', p: 'Los allanamientos no figuran entre las autorizaciones posibles.'},
{a: 'art. 19.9 y 19.10', r: 'Artículo 19. Impugnación de la competencia de la Corte o de la admisibilidad de la causa', e: 'La impugnación no afectará a la validez de ningún acto realizado por el fiscal, ni de ninguna orden o mandamiento dictado por la Corte, antes de ella. Si la Corte hubiere declarado inadmisible una causa, el fiscal podrá pedir que se revise esa decisión cuando se haya cerciorado cabalmente de que han aparecido:',
 o: ['nuevos hechos que invalidan los motivos por los cuales la causa había sido considerada inadmisible.', 'nuevas pruebas que acrediten la responsabilidad del acusado.', 'nuevos hechos que justifiquen la apertura de una investigación distinta.', 'nuevos testigos que contradigan la decisión de inadmisibilidad.'],
 t: 'el fiscal podrá pedir que se revise esa decisión cuando se haya cerciorado cabalmente de que han aparecido nuevos hechos que invalidan los motivos por los cuales la causa había sido considerada inadmisible de conformidad con dicho artículo', p: 'La revisión exige nuevos hechos que invaliden los motivos de la inadmisibilidad.'},
{a: 'art. 20.1 y 20.2', r: 'Artículo 20. Cosa juzgada', e: 'Salvo que el Estatuto disponga otra cosa, nadie será procesado por la Corte en razón de conductas constitutivas de crímenes por los cuales ya hubiere sido condenado o absuelto por la Corte. Además:',
 o: ['nadie será procesado por otro tribunal en razón de uno de los crímenes mencionados en el artículo 5 por el cual la Corte ya le hubiere condenado o absuelto.', 'nadie será procesado por otro tribunal en razón de uno de los crímenes mencionados en el artículo 5 por el cual la Corte ya le hubiere condenado, pero sí por el que le hubiere absuelto.', 'nadie será procesado por otro tribunal en razón de cualquier crimen por el cual la Corte ya le hubiere condenado o absuelto.', 'podrá ser procesado por otro tribunal en razón de uno de los crímenes del artículo 5 si el tribunal es de un Estado Parte.'],
 t: 'Nadie será procesado por otro tribunal en razón de uno de los crímenes mencionados en el artículo 5 por el cual la Corte ya le hubiere condenado o absuelto', p: 'Se protege tanto contra la condena como contra la absolución de la Corte, y solo para los crímenes del art. 5.'},
{a: 'art. 20.3', r: 'Artículo 20. Cosa juzgada', e: 'La Corte no procesará a nadie que haya sido procesado por otro tribunal en razón de hechos también prohibidos en virtud de los artículos 6, 7, 8 u 8 bis a menos que el proceso en el otro tribunal (señale la INCORRECTA):',
 o: ['Hubiere concluido con una sentencia más favorable que la que pudiera dictar la Corte.', 'Obedeciera al propósito de sustraer al acusado de su responsabilidad penal por crímenes de la competencia de la Corte.', 'No hubiere sido instruido en forma independiente o imparcial de conformidad con las debidas garantías procesales reconocidas por el derecho internacional.', 'Hubiere sido instruido de alguna manera que, en las circunstancias del caso, fuere incompatible con la intención de someter a la persona a la acción de la justicia.'],
 t: 'a) Obedeciera al propósito de sustraer al acusado de su responsabilidad penal por crímenes de la competencia de la Corte; o b) No hubiere sido instruido en forma independiente o imparcial de conformidad con las debidas garantías procesales reconocidas por el derecho internacional o lo hubiere sido de alguna manera que, en las circunstancias del caso, fuere incompatible con la intención de someter a la persona a la acción de la justicia', p: 'Solo hay dos supuestos (a y b); la benignidad de la sentencia no es uno de ellos.'},
{a: 'art. 21.1', r: 'Artículo 21. Derecho aplicable', e: 'La Corte aplicará, EN PRIMER LUGAR:',
 o: ['el Estatuto, los Elementos de los crímenes y sus Reglas de Procedimiento y Prueba.', 'el Estatuto y los tratados aplicables, los principios y normas del derecho internacional.', 'el Estatuto, los Convenios de Ginebra y las Reglas de Procedimiento y Prueba.', 'el Estatuto y los principios generales del derecho que derive la Corte del derecho interno.'],
 t: 'a) EN PRIMER LUGAR, el presente Estatuto, los Elementos de los crímenes y sus Reglas de Procedimiento y Prueba', p: 'El orden es: 1.º Estatuto, Elementos y Reglas; 2.º tratados y principios del derecho internacional; 3.º en su defecto, principios generales del derecho interno.'},
{a: 'art. 21.1.c)', r: 'Artículo 21. Derecho aplicable', e: 'La Corte aplicará, EN SU DEFECTO, los principios generales del derecho que derive la Corte del derecho interno de los sistemas jurídicos del mundo, incluido, cuando proceda, el derecho interno de los Estados que normalmente ejercerían jurisdicción sobre el crimen, siempre que esos principios:',
 o: ['no sean incompatibles con el Estatuto ni con el derecho internacional ni las normas y estándares internacionales reconocidas.', 'no sean incompatibles con el Estatuto ni con el derecho interno del Estado que ejerza la jurisdicción.', 'no sean incompatibles con los Elementos de los crímenes ni con las Reglas de Procedimiento y Prueba.', 'hayan sido reconocidos por la mayoría de los Estados Partes en el Estatuto.'],
 t: 'siempre que esos principios no sean incompatibles con el presente Estatuto ni con el derecho internacional ni las normas y estándares internacionales reconocidas', p: 'Han de ser compatibles con el Estatuto, el derecho internacional y los estándares internacionales.'},
{a: 'art. 21.2 y 21.3', r: 'Artículo 21. Derecho aplicable', e: 'La aplicación e interpretación del derecho de conformidad con el artículo 21 deberá ser compatible con los derechos humanos internacionalmente reconocidos, sin distinción alguna basada en motivos como (señale la INCORRECTA):',
 o: ['La orientación política del tribunal que conozca del asunto.', 'El género, definido en el párrafo 3 del artículo 7, la edad, la raza, el color, el idioma, religión o el credo.', 'La opinión política o de otra índole, el origen nacional, étnico o social.', 'La posición económica, el nacimiento u otra condición.'],
 t: 'sin distinción alguna basada en motivos como el género, definido en el párrafo 3 del artículo 7, la edad, la raza, el color, el idioma, religión o el credo, la opinión política o de otra índole, el origen nacional, étnico o social, la posición económica, el nacimiento u otra condición', p: 'La orientación del tribunal no figura entre los motivos de no discriminación.'},
{a: 'art. 21.2', r: 'Artículo 21. Derecho aplicable', e: 'La Corte podrá aplicar principios y normas de derecho respecto de los cuales hubiere hecho una interpretación en:',
 o: ['decisiones anteriores.', 'sentencias firmes de la Sala de Apelaciones.', 'resoluciones del Consejo de Seguridad.', 'decisiones anteriores de la Presidencia.'],
 t: 'La Corte podrá aplicar principios y normas de derecho respecto de los cuales hubiere hecho una interpretación en decisiones anteriores', p: 'Se alude a las decisiones anteriores de la propia Corte.'},
];
